    let hot=document.getElementById("hot").selectedIndex;

    let ac1=document.getElementById("ac1").checked;
    let ac2=document.getElementById("ac2").checked;
    let ac3=document.getElementById("ac3").checked;

    let res1=document.getElementById("res1").checked;
    let res2=document.getElementById("res2").checked;
    let res3=document.getElementById("res3").checked;

    let captcha=document.getElementById("cap").value;
    let rep=document.getElementById("rep").value;


    if(hot===0){
        alert("choisir un hotel SVP !")
        return false
    }
    if(!ac1 & !ac2 & !ac3){
        alert("choisir un acceuil SVP !")
        return false
    }
    if(!res1 & !res2 & !res3){
        alert("choisir un restauration SVP !")
        return false
    }
    if( verifMaj(captcha) && rep!="1")  {
        alert("reponse incorrect!")
        return false
    }
    if(!verifMaj(captcha) && rep!="0") {
        alert("reponse incorrect!")
        return false
    }
    
    
}

function GenererCaptcha() {
    let k = Math.floor(Math.random() * 26)+1;
    console.log(k);

    let ch;
    if (k % 2 === 0) {
        ch = String.fromCharCode('A'.charCodeAt(0) + k-1);
    } else {
        ch = String.fromCharCode('a'.charCodeAt(0) + k-1);
    }

    console.log(ch);
    document.getElementById("cap").value = ch;
}

function verifMaj(ch) {
    let i = 0;
    while (i < ch.length && ch[i] >= "A" && ch[i] <= "Z") {
        i++;
    }
    return i === ch.length;
}

